 const p=currentProject();if(!p)return;
 const tabs=$('fichaTabs'),list=$('fichaList');tabs.innerHTML='';list.innerHTML='';
 if(!Array.isArray(p.fichas))p.fichas=[];
 if(!p.fichas.length){p.fichas=FICHA_TEMPLATES.map((_,i)=>blankFicha(i+1));}
 if(!p.activeFichaId||!p.fichas.some(f=>f.id===p.activeFichaId))p.activeFichaId=p.fichas[0].id;
 p.fichas.forEach((f,i)=>{const b=document.createElement('button');b.type='button';b.className='ficha-tab'+(f.id===p.activeFichaId?' active':'');b.dataset.fichaTab=f.id;b.innerHTML=`<span>${String(i+1).padStart(2,'0')}</span><small>${esc((f.title||templateFor(f,i)?.title||`Ficha ${i+1}`).replace(/^Ficha \d+\s*[—-]?\s*/i,''))}</small>`;tabs.append(b);});
 const i=p.fichas.findIndex(f=>f.id===p.activeFichaId),f=p.fichas[i];$('fichaStepLabel').textContent=`Ficha ${i+1} de ${p.fichas.length}`;$('prevFicha').disabled=i===0;$('nextFicha').disabled=i===p.fichas.length-1;
 const el=document.createElement('article');el.className='ficha-card';el.dataset.fichaCard=f.id;
 el.innerHTML=`<div class="ficha-head"><div><h3>${esc(f.title||`Ficha ${String(i+1).padStart(2,'0')}`)}</h3><p class="ficha-count">Etapa ${i+1} de ${p.fichas.length}${f.isAdditional?' · ficha adicional':''}</p></div><div><button data-copy-ficha="${f.id}">Duplicar</button> <button class="danger" data-delete-ficha="${f.id}">Excluir</button></div></div><p class="ficha-guide">${esc(f.guide||templateFor(f)?.guide||'Ficha preservada de versão anterior; revise seu tipo e conteúdo.')}</p><details class="ficha-general-fields" open><summary>Identificação da etapa</summary><div class="ficha-grid"><label>Título<input data-f="title" value="${esc(f.title)}"></label><label>Estado<select data-f="status">${['Planejada','Em preparação','Testada','Aprovada','Descartada'].map(st=>`<option ${f.status===st?'selected':''}>${st}</option>`).join('')}</select></label><label>Cena / sequência<input data-f="scene" value="${esc(f.scene)}" placeholder="Cena 04 / sequência B"></label><label>Setup<input data-f="setup" value="${esc(f.setup)}" placeholder="Setup A, B, C…"></label><label>Local / cenário<input data-f="location" value="${esc(f.location)}"></label><label>Data<input data-f="date" type="date" value="${esc(f.date)}"></label><label class="full">Referência visual (opcional)<input data-f="reference" value="${esc(f.reference)}" placeholder="Filme, plano ou imagem"></label></div></details><section class="ficha-specific-section"><h4>${esc((templateFor(f)?.title||f.title||'Ficha adicional').replace(/^Ficha \d+\s*[—-]?\s*/i,''))}</h4><p class="muted">Preencha somente o que pertence a esta etapa. Dados de câmera, medições e solução aparecem na etapa correspondente, evitando repetição.</p><div class="ficha-specific-grid">${(templateFor(f)?.fields||[]).map(([key,label])=>`<label>${esc(label)}<small class="field-help">${esc(FIELD_HELP[key]||'Registre a informação necessária para esta etapa.')}</small><textarea data-specific="${key}" rows="2" placeholder="Escreva de forma objetiva…">${esc(f.specific?.[key]||'')}</textarea></label>`).join('')||'<p class="muted">Esta ficha adicional não tem campos predefinidos. Use as observações para registrar o conteúdo legado sem alterar a estrutura das seis etapas.</p>'}</div></section><details class="ficha-general-fields"><summary>Equipamentos associados e observações</summary><div class="ficha-grid"><label class="full">Equipamentos usados nesta ficha<div class="ficha-gear-list">${(f.equipmentIds||[]).map(id=>{const g=data.gear.find(x=>x.id===id);return g?`<span class="chip">${esc(g.name)} <button data-remove-ficha-gear="${f.id}" data-gear-id="${id}" aria-label="Remover ${esc(g.name)}">×</button></span>`:''}).join('')}</div><div class="autocomplete-wrap"><input autocomplete="off" data-ficha-gear-input="${f.id}" placeholder="Buscar equipamento na biblioteca…"><div class="autocomplete-results" data-results-for="${f.id}" hidden></div></div><small class="muted">Cadastre novos itens na aba Biblioteca.</small></label><label class="full">Observações / conteúdo legado preservado<textarea data-f="notes" rows="3">${esc(f.notes)}</textarea></label></div></details>`;
