$('gearForm').onsubmit=e=>{e.preventDefault();const name=$('gearName').value.trim();if(!name)return;const existing=data.gear.find(g=>g.name.toLowerCase()===name.toLowerCase());if(existing){alert('Já existe um equipamento com esse nome. Edite o cadastro existente ou escolha outro nome.');return;}data.gear.push({id:uid(),name,category:$('gearCategory').value,brand:$('gearBrand').value.trim(),model:$('gearModel').value.trim(),qty:Number($('gearQty').value)||0,notes:$('gearNotes').value.trim(),createdAt:now()});e.target.reset();$('gearQty').value='1';save();renderGear();};
$('gearSearch').oninput=renderGear;$('gearFilter').onchange=renderGear;
function renderGear(){const list=$('gearList');if(!list)return;const q=($('gearSearch')?.value||'').toLowerCase(),cat=$('gearFilter')?.value||'Todas';list.innerHTML='';data.gear.filter(g=>(cat==='Todas'||g.category===cat)&&[g.name,g.brand,g.model,g.notes,g.category].join(' ').toLowerCase().includes(q)).forEach(g=>{const el=document.createElement('div');el.className='gear-row';el.innerHTML=`<div><strong>${esc(g.name)}</strong><div class="muted tiny">${esc([g.category,g.brand,g.model].filter(Boolean).join(' · '))} · Qtd.: ${g.qty}</div>${g.notes?`<div class="muted tiny">${esc(g.notes)}</div>`:''}</div><div><button data-edit-gear="${g.id}">Editar</button> <button class="danger" data-delete-gear="${g.id}">Excluir</button></div>`;list.append(el);});}
$('gearList').onclick=async e=>{const b=e.target.closest('button');if(!b)return;const g=data.gear.find(x=>x.id===b.dataset.editGear||x.id===b.dataset.deleteGear);if(!g)return;if(b.dataset.editGear){$('gearName').value=g.name;$('gearCategory').value=g.category;$('gearBrand').value=g.brand;$('gearModel').value=g.model;$('gearQty').value=g.qty;$('gearNotes').value=g.notes;const form=$('gearForm');form.dataset.editId=g.id;form.querySelector('button[type="submit"]').textContent='Salvar alterações';form.scrollIntoView({behavior:'smooth'});return;}if(b.dataset.deleteGear&&await confirmAction(`Excluir “${g.name}” da biblioteca? As referências existentes serão mantidas como texto nas fichas.`)){data.gear=data.gear.filter(x=>x.id!==g.id);data.projects.forEach(p=>p.objects.forEach(o=>{if(o.gearId===g.id){o.gearId='';o.gearName=g.name;}}));save();renderGear();renderFichas();}};
// Intercept edit submission safely
const gearForm=$('gearForm');gearForm.addEventListener('submit',e=>{const id=gearForm.dataset.editId;if(!id)return;e.preventDefault();e.stopImmediatePropagation();const g=data.gear.find(x=>x.id===id);if(!g)return;g.name=$('gearName').value.trim();g.category=$('gearCategory').value;g.brand=$('gearBrand').value.trim();g.model=$('gearModel').value.trim();g.qty=Number($('gearQty').value)||0;g.notes=$('gearNotes').value.trim();delete gearForm.dataset.editId;gearForm.querySelector('button[type="submit"]').textContent='+ Salvar equipamento';gearForm.reset();$('gearQty').value='1';save();renderGear();renderFichas();},{capture:true});
const canvas=$('sceneCanvas');canvasCtx=canvas.getContext('2d');function resizeCanvas(){if(!canvas||!canvasCtx)return;const r=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.round(r.width*dpr));canvas.height=Math.max(1,Math.round(r.height*dpr));canvasCtx.setTransform(dpr,0,0,dpr,0,0);drawScene();}window.addEventListener('resize',resizeCanvas);
function objects(){return currentProject()?.objects||[];}function addObject(){const p=ensureProject();if(!p)return;const type=$('objectType').value;const names={light:'Luz',camera:'Câmera',subject:'Personagem',chair:'Cadeira',table:'Mesa',sofa:'Sofá',wall:'Parede',window:'Janela',flag:'Bandeira / difusão',stand:'Tripé / suporte'};const o={id:uid(),type,name:names[type],x:0,y:0,z:type==='light'?2.5:0,rot:type==='light'?180:0,angle:45,range:5,lightType:'LED / COB',on:true,gearId:'',gearName:'',createdAt:now()};p.objects.push(o);p.updatedAt=now();selectedObjectId=o.id;save();renderObjects();editSelected();drawScene();}
$('addObject').onclick=addObject;$('zoomIn').onclick=()=>{zoom=Math.min(zoom*1.2,5);persistView();drawScene();};$('zoomOut').onclick=()=>{zoom=Math.max(zoom/1.2,.35);persistView();drawScene();};$('resetView').onclick=()=>{zoom=1;panX=0;panY=0;persistView();drawScene();};['showCone','showCoverage','showLabels','showGrid'].forEach(id=>$(id).onchange=drawScene);document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{currentView=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));drawScene();});
function persistView(){const p=currentProject();if(p){p.view={zoom,panX,panY};p.updatedAt=now();saveSoon();}}
function syncRoomInputs(p=currentProject()){if(!p)return;const r=p.room||{width:10,length:10,height:'',backdropWidth:3,backdropHeight:4.4,backdropWall:'north'};[['roomWidth','width'],['roomLength','length'],['roomHeight','height'],['backdropWidth','backdropWidth'],['backdropHeight','backdropHeight'],['backdropWall','backdropWall']].forEach(([id,key])=>{if($(id))$(id).value=r[key]??({width:10,length:10,height:'',backdropWidth:3,backdropHeight:4.4,backdropWall:'north'}[key]);});}
function applyRoomDimensions(){const p=currentProject();if(!p)return;const n=id=>Number($(id).value);const hRaw=$('roomHeight').value.trim();const vals={width:n('roomWidth'),length:n('roomLength'),height:hRaw?Number(hRaw):null,backdropWidth:n('backdropWidth'),backdropHeight:n('backdropHeight'),backdropWall:$('backdropWall').value};if(['width','length','backdropWidth','backdropHeight'].some(k=>!Number.isFinite(vals[k])||vals[k]<=0)||(vals.height!==null&&(!Number.isFinite(vals.height)||vals.height<=0))){alert('Todas as dimensões precisam ser números maiores que zero.');syncRoomInputs(p);return;}if(vals.backdropWidth>(vals.backdropWall==='north'||vals.backdropWall==='south'?vals.width:vals.length)){alert('A largura do fundo não cabe nessa parede. Reduza a largura do fundo ou escolha outra parede.');return;}p.room=vals;p.updatedAt=now();save();drawScene();renderObjects();}
$('applyRoom')?.addEventListener('click',applyRoomDimensions);

function renderObjects(){const list=$('objectList');if(!list)return;list.innerHTML='';objects().forEach(o=>{const el=document.createElement('div');el.className='object-row';el.innerHTML=`<button data-select-object="${o.id}">${esc(o.name)}</button><span class="muted tiny">${esc(({light:'Luz',camera:'Câmera',subject:'Personagem',chair:'Cadeira',table:'Mesa',sofa:'Sofá',wall:'Parede',window:'Janela',flag:'Bandeira / difusão',stand:'Tripé / suporte'})[o.type]||o.type)} · X ${Number(o.x).toFixed(1)} / Y ${Number(o.y).toFixed(1)}${o.type==='light'?' · '+(o.on?'Ligada':'Desligada'):''}</span>`;list.append(el);});}
$('objectList').onclick=e=>{const b=e.target.closest('[data-select-object]');if(b){selectedObjectId=b.dataset.selectObject;editSelected();drawScene();}};
function editSelected(){const o=objects().find(x=>x.id===selectedObjectId);$('emptySelection').hidden=!!o;$('objectEditor').hidden=!o;if(!o)return;$('objName').value=o.name;$('objGear').value=data.gear.find(g=>g.id===o.gearId)?.name||o.gearName||'';$('objX').value=o.x;$('objY').value=o.y;$('objZ').value=o.z;$('objRot').value=o.rot;$('objAngle').value=o.angle;$('objRange').value=o.range;$('objLightType').value=o.lightType||'LED / COB';$('objOn').checked=o.on!==false;$('lightSettings').hidden=o.type!=='light';}
function updateSelected(field,value){const p=currentProject(),o=objects().find(x=>x.id===selectedObjectId);if(!p||!o)return;o[field]=value;if(field==='gearName'){const g=data.gear.find(g=>g.name.toLowerCase()===String(value).trim().toLowerCase());o.gearId=g?.id||'';o.gearName=g?.name||String(value);}p.updatedAt=now();saveSoon();renderObjects();drawScene();}
[['objName','name','string'],['objX','x','number'],['objY','y','number'],['objZ','z','number'],['objRot','rot','number'],['objAngle','angle','number'],['objRange','range','number'],['objLightType','lightType','string']].forEach(([id,field,type])=>$(id).addEventListener('change',e=>updateSelected(field,type==='number'?Number(e.target.value)||0:e.target.value)));['rotateMinus','rotatePlus','rotateReset'].forEach(id=>$(id).onclick=()=>{const o=objects().find(x=>x.id===selectedObjectId);if(!o)return;o.rot=id==='rotateReset'?0:((Number(o.rot)||0)+(id==='rotatePlus'?15:-15)+360)%360;$('objRot').value=o.rot;updateSelected('rot',o.rot);editSelected();drawScene();});function showSuggestions(input,box,query,onChoose){if(!box)return;const q=String(query||'').trim();box.innerHTML='';if(!q){box.hidden=true;return;}const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');const nq=norm(q);const matches=data.gear.map(g=>{const fields=[g.name,g.brand,g.model,g.category];const hay=fields.map(norm);const score=hay.some(v=>v.startsWith(nq))?0:hay.some(v=>v.split(/\s+/).some(t=>t.startsWith(nq)))?1:hay.some(v=>v.includes(nq))?2:99;return {g,score};}).filter(x=>x.score<99).sort((a,b)=>a.score-b.score||a.g.name.localeCompare(b.g.name,'pt-BR')).slice(0,8);matches.forEach(({g},i)=>{const b=document.createElement('button');b.type='button';b.className='suggestion-item';b.setAttribute('role','option');b.innerHTML=`<strong>${esc(g.name)}</strong><small>${esc([g.category,g.brand,g.model].filter(Boolean).join(' · '))} · Qtd.: ${Number(g.qty||0)}</small>`;const choose=e=>{e.preventDefault();e.stopPropagation();onChoose(g);box.hidden=true;};b.addEventListener('pointerdown',choose);b.addEventListener('click',choose);box.append(b);});if(!matches.length){const p=document.createElement('div');p.className='suggestion-empty';p.textContent='Nenhum resultado. Cadastre o item na Biblioteca.';box.append(p);}box.hidden=false;}
$('objGear').addEventListener('input',e=>showSuggestions(e.target,$('objGearResults'),e.target.value,g=>{updateSelected('gearName',g.name);$('objGear').value=g.name;}));$('objGear').addEventListener('focus',e=>{if(e.target.value)showSuggestions(e.target,$('objGearResults'),e.target.value,g=>{updateSelected('gearName',g.name);e.target.value=g.name;});});$('objGear').addEventListener('change',e=>{const g=data.gear.find(x=>x.name.toLocaleLowerCase('pt-BR')===e.target.value.trim().toLocaleLowerCase('pt-BR'));if(g)updateSelected('gearName',g.name);else if(e.target.value.trim()){e.target.value='';alert('Escolha um equipamento da lista de sugestões. Para criar um novo, use a Biblioteca.');}});document.addEventListener('pointerdown',e=>{if(!e.target.closest('.autocomplete-wrap'))document.querySelectorAll('.autocomplete-results').forEach(b=>b.hidden=true);});
$('fichaList').addEventListener('input',e=>{const input=e.target.closest('[data-ficha-gear-input]');if(!input)return;const box=input.parentElement.querySelector('.autocomplete-results');showSuggestions(input,box,input.value,g=>{const p=currentProject(),f=p?.fichas.find(x=>x.id===input.dataset.fichaGearInput);if(!p||!f)return;f.equipmentIds=f.equipmentIds||[];if(!f.equipmentIds.includes(g.id))f.equipmentIds.push(g.id);f.updatedAt=now();p.updatedAt=now();save();renderFichas();});});$('objOn').onchange=e=>updateSelected('on',e.target.checked);$('deleteObject').onclick=async()=>{const p=currentProject();if(!p)return;const o=objects().find(x=>x.id===selectedObjectId);if(o&&await confirmAction(`Excluir “${o.name}” da planta?`)){p.objects=p.objects.filter(x=>x.id!==o.id);selectedObjectId=null;save();renderObjects();editSelected();drawScene();}};
function beamGeometry(rotDeg,angleDeg){const rot=(Number(rotDeg)||0)*Math.PI/180,half=Math.max(0,Math.min(360,Number(angleDeg)||45))*Math.PI/360;return {center:-rot,start:-rot-half,end:-rot+half,dx:Math.cos(rot),dy:-Math.sin(rot)};}
function drawBeamArrow(ctx,x,y,r,rotDeg,angleDeg,opts={}){const g=beamGeometry(rotDeg,angleDeg),ex=x+g.dx*r,ey=y+g.dy*r;ctx.save();ctx.strokeStyle=opts.color||'#b88a3d';ctx.fillStyle=opts.color||'#b88a3d';ctx.lineWidth=opts.lineWidth||1.8;ctx.setLineDash(opts.dashed?[5,4]:[]);ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(ex,ey);ctx.stroke();ctx.setLineDash([]);const a=Math.atan2(ey-y,ex-x),head=Math.max(7,Math.min(13,r*.06));ctx.beginPath();ctx.moveTo(ex,ey);ctx.lineTo(ex-head*Math.cos(a-.48),ey-head*Math.sin(a-.48));ctx.lineTo(ex-head*Math.cos(a+.48),ey-head*Math.sin(a+.48));ctx.closePath();ctx.fill();ctx.restore();}
